# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_greek_leg_a import G,X,H
DY=X+[['近代医学用希腊 dys- 与 lexis 材料造词；德语 Dyslexie 等形式','阅读方面的困难'],['英语 dyslexia','阅读障碍']]
AX=X+[['近代用 a-、lexis 与 -ia 构成 alexia','无、缺失 + 词语 + 状态'],['英语 alexia','后天获得的阅读能力障碍、失读症']]
AT=X+[['20世纪医学用 a- + lexis + thymos + -ia 构成 alexithymia','缺少 + 言语 + 情感 + 状态'],['英语 alexithymia','难以辨认、说清自己的情绪']]
WD=[
E('lexicologist','英 /ˌleksɪˈkɒlədʒɪst/；美 /ˌleksɪˈkɑːlədʒɪst/','词汇学家；研究词汇的人','把词当作一个彼此连接的系统，研究它们怎么组成、怎么变化。','lexicology 对应的 -ist 人称名词，接 lexico-“词汇”与 -logy“研究”的学术构词。',X+[['法语 lexicologie → 英语 lexicology','词汇学'],['英语 lexicologist','从事词汇研究的人']],'lexicologist 可能研究新词怎么形成、同义词有什么差别、一个词的意思如何变化。他可以使用词典，但工作不一定是编词典。这个词重在研究对象是词汇，而不是说他会背特别多单词。','a historical lexicologist；work as a lexicologist；lexicologists and lexicographers。','lexicologist 研究词汇；lexicographer 编写或研究词典。两种工作可以由同一个人承担。',('The lexicologist traced changes in the word’s meaning.','词汇学家追踪了这个词的词义变化。'),('A lexicologist studies relationships within a vocabulary.','词汇学家研究一个词汇系统内部的关系。'),sources=['https://www.merriam-webster.com/dictionary/lexicologist','https://en.wiktionary.org/wiki/lexicologist']),
E('lexigram','/ˈleksɪɡræm/','代表一个词或概念的图形符号','用一个约定好的图形充当词的按钮；按下它，就表达相应的东西或动作。','lexi-“词语” + -gram“写出的符号、记录”，是现代组合词。',X+[['现代 lexi- + -gram → lexigram','词语 + 符号 → 代表词或概念的图形']],'一些动物交流研究用 lexigram 键盘：不同几何符号代表食物、地点或动作。符号未必画得像它代表的东西，学习者要建立对应关系。能使用这些符号是具体研究结果，不等于已经具备人类语言的全部能力。','a lexigram keyboard；select a lexigram；a lexigram representing food。','lexigram 可以是任意约定的符号；pictogram 通常通过外形画出所代表的事物。二者不能完全等同。',('The participant selected a lexigram representing a banana.','参与者选中了代表香蕉的图形符号。'),('Each lexigram on the board had an assigned meaning.','板上的每个图形符号都有约定的含义。'),sources=['https://en.wiktionary.org/wiki/lexigram','https://pmc.ncbi.nlm.nih.gov/articles/PMC3399965/']),
E('dyslexia','/dɪsˈleksiə/','阅读障碍，常涉及认词、拼读或拼写方面的困难','脑中知道想说什么，但把纸上的字母稳定地接成词，可能格外费劲。','dys-“困难、异常” + lexi-“词语” + -ia；这是近代医学用希腊语材料创造的术语，不是古希腊已有的同名诊断。',DY,'日常教育语境中的 dyslexia 常说持续的阅读和拼写困难，具体表现因人而异。它不等于智力低、懒惰，也不意味着所有人都把字母看反。词根里的“词语”在这个术语中落到了阅读处理这一具体方面。','have dyslexia；support for dyslexia；a student with dyslexia。','dyslexia 常用于发展性阅读困难；alexia 通常说脑损伤等之后出现的失读。实际医学分类还可能使用 acquired dyslexia。',('She has dyslexia and uses audio versions of some course materials.','她有阅读障碍，会使用部分课程材料的音频版。'),('Dyslexia does not measure a person’s intelligence.','阅读障碍不能衡量一个人的智力。'),sources=['https://www.etymonline.com/word/dyslexia','https://www.nhs.uk/conditions/dyslexia-in-children/']),
E('dyslexic','/dɪsˈleksɪk/','有阅读障碍的；与阅读障碍有关的','说的是阅读处理上的困难，不是在给一个人的全部能力打分。','与 dyslexia 对应的 -ic 形容词形式；不是把 dys- 单独解释成“坏人”或“低能力”。',H(DY,'英语 dyslexic','有阅读障碍的；也可作指人的名词'),'a dyslexic student 可以理解为一位有阅读障碍的学生。它也有名词用法，但具体写作中 a person with dyslexia 往往更直接。不要因为有人拼错一个词，就随口给对方贴上 dyslexic 标签。','dyslexic readers；dyslexic students；dyslexic difficulties。','dyslexic 不等于 illiterate。前者涉及阅读处理困难；后者通常说不会读写，原因可以很多。',('The library provides resources for dyslexic readers.','图书馆为有阅读障碍的读者提供资料支持。'),('Being dyslexic has not stopped her from becoming a skilled engineer.','阅读障碍并没有阻止她成为一名优秀工程师。'),sources=['https://www.etymonline.com/word/dyslexic','https://dictionary.cambridge.org/dictionary/english/dyslexic','https://www.nhs.uk/conditions/dyslexia-in-children/']),
E('dyslectic','/dɪsˈlektɪk/','有阅读障碍的；有阅读障碍者〔较少用的形式〕','意思与 dyslexic 接近，只是词尾换成了 -lectic。','与 dyslexia 同族的形容词变体，词形使用 -lectic；不要把其中的 lect 硬解释为英语 lecture。',H(DY,'英语 dyslectic','与 dyslexic 意义相近的较少见形式'),'阅读旧文章或专业讨论时可能遇到 dyslectic。它可以作形容词，也可以作指人的名词；一般交流中 dyslexic 或 person with dyslexia 更容易被识别。两种拼写并不代表两种严重程度。','a dyslectic reader；dyslectic pupils；the term dyslectic。','dyslectic 与 dyslexic 主要是用词形式的差别，不能据此推断不同诊断。',('The older article uses “dyslectic” to describe readers with dyslexia.','这篇较早的文章用 dyslectic 描述有阅读障碍的读者。'),('The school offered extra reading support to dyslectic pupils.','学校为有阅读障碍的学生提供额外阅读支持。'),sources=['https://www.merriam-webster.com/medical/dyslectic','https://www.dictionary.com/browse/dyslectic','https://en.wiktionary.org/wiki/dyslectic']),
E('alexia','/əˈleksiə/','失读症；后天获得的阅读能力障碍','以前能读懂的文字，后来在大脑处理文字的环节上出了障碍。','a-“缺失” + lex-“词语” + -ia，是近代医学组合词；词尾并不表示某个具体器官。',AX,'alexia 常用于脑损伤等之后出现的阅读困难或丧失，程度和类型并不相同。有些人仍能写，却难以读懂写下的内容；这说明阅读和书写虽然相关，也可能受不同影响。不要把不会某种外语或从未学过阅读叫作 alexia。','acquired alexia；pure alexia；alexia without agraphia。','alexia 关注阅读障碍；agraphia 关注书写障碍；aphasia 涉及更广的语言功能，三者不能随意互换。',('The study examined reading difficulties in people with alexia.','研究考察了失读症患者的阅读困难。'),('The patient could write a sentence but had difficulty reading it because of alexia.','这位患者能写出句子，却因失读症难以读懂它。'),sources=['https://www.etymonline.com/word/alexia','https://pubmed.ncbi.nlm.nih.gov/7145079/','https://pmc.ncbi.nlm.nih.gov/articles/PMC2077748/']),
E('dyslexically','按构词读法 /dɪsˈleksɪkli/','以与阅读障碍相关的方式〔少用〕','用副词形式描述阅读障碍相关的处理特点，但说清具体困难通常更好懂。','dyslexic + -ally；构成副词时写作 dyslexically。',H(DY,'英语 dyslexic → dyslexically','有阅读障碍的 → 以相关方式'),'这个副词确有用例，但远不如 dyslexia 和 dyslexic 常用。单写 someone reads dyslexically 很笼统：到底是认词慢、拼读费力，还是其他困难？实际交流往往应把具体情况说出来，不能把它当“粗心地”的同义词。','process text dyslexically〔较少见〕；the adverb dyslexically。','dyslexically 不是 carelessly。阅读障碍相关困难与有没有认真是两回事。',('The paper uses “dyslexically” when discussing how some readers process text.','论文在讨论某些读者处理文字的方式时用了 dyslexically 这个词。'),('She describes her experience as processing written language dyslexically.','她把自己的体验描述为以阅读障碍相关的方式处理书面语言。'),sources=['https://en.wiktionary.org/wiki/dyslexically','https://www.nhs.uk/conditions/dyslexia-in-children/']),
E('alexithymia','/əˌleksɪˈθaɪmiə/','述情障碍；难以辨认和描述自己的情绪','心里有感受，却很难分清是什么，也很难把它说成话。','a-“缺少” + lexi-“言语” + thym-“情感” + -ia，可用“难以给情绪找到词”帮助理解；这是20世纪创造的术语。',AT,'alexithymia 常涉及辨认、描述自身情绪的困难。一个人可能知道自己不舒服，却难以分清是害怕、愤怒还是难过。这个词不表示完全没有情绪，也不能仅凭一个人沉默或不善聊天就判断他有这种特征。','alexithymia scores；features of alexithymia；difficulty associated with alexithymia。','alexithymia 关乎认识和表达情绪的困难；shyness 关乎社交中的害羞。会害羞的人仍可能很清楚自己的感受。',('The study measured alexithymia with a questionnaire.','研究用问卷测量了述情困难的相关特征。'),('Alexithymia can make it difficult to put feelings into words.','述情障碍可能让人难以把感受说成话。'),sources=['https://en.wiktionary.org/wiki/alexithymia','https://pmc.ncbi.nlm.nih.gov/articles/PMC8456171/','https://pubmed.ncbi.nlm.nih.gov/29792440/']),
E('alexithymic','/əˌleksɪˈθaɪmɪk/','有述情困难特征的；与述情障碍有关的','情绪已经发生，但给情绪辨认身份、找到名字这一步比较困难。','与 alexithymia 对应的 -ic 形容词形式，保留 a-、lexi-、thym- 这些希腊语构词材料。',H(AT,'英语 alexithymic','表现出或涉及述情困难的'),'研究中 alexithymic traits 指相关特征，可以用量表等方式考察。它并不等于 cold“冷酷的”，更不是说某人没有感情。描述具体表现，比把整个人简单称作 an alexithymic 更清楚。','alexithymic traits；alexithymic features；alexithymic difficulties。','alexithymic 说情绪识别、表达困难；unemotional 常说外表不动感情或缺少情绪表现，范围不同。',('The researchers compared participants with different levels of alexithymic traits.','研究者比较了述情困难特征程度不同的参与者。'),('Alexithymic difficulties do not mean that a person has no feelings.','述情方面的困难并不意味着一个人没有感受。'),sources=['https://en.wiktionary.org/wiki/alexithymic','https://pmc.ncbi.nlm.nih.gov/articles/PMC8456171/']),
E('dyslogia','美 /dɪsˈloʊdʒiə/，也读 /dɪsˈloʊdʒə/','思维障碍相关的言语表达困难〔较旧医学用语〕','想法的组织或表达出了问题，结果难以把意思连贯地说出来。','dys-“异常、困难” + log-“话语、推理” + -ia，通过近代医学拉丁语构成。',G+[['希腊 logos“话语、推理”与 dys-、-ia 结合 → 新拉丁 dyslogia','思维、表达方面的异常'],['英语 dyslogia','与思维障碍等相关的言语表达困难']],'这个少见术语出现在较旧医学或术语材料中，关注思维或精神障碍相关的表达问题。它不是普通的“不会说话”，也不适合拿来形容演讲紧张、偶尔找不到一个词。阅读时识别即可，实际专业用词要看文献的具体定义。','the term dyslogia；a historical description of dyslogia。','dyslogia 不等于 dyslexia；前者涉及思维与言语表达，后者核心在阅读。也别与 dyslogy“贬斥、责难”混淆。',('The historical text uses “dyslogia” for a disturbance of verbal expression.','这份历史文本用 dyslogia 指一种言语表达障碍。'),('The glossary distinguishes dyslogia from dyslexia.','术语表把 dyslogia 与 dyslexia 区分开来。'),sources=['https://www.dictionary.com/browse/dyslogia','https://vitrinelinguistique.oqlf.gouv.qc.ca/fiche-gdt/fiche/17063243/dyslogie']),
]
